class _Armed(weakref.ref):
    """Weak reference whose callback is the C destroy function itself.

    ctypes passes the reference to it as its ``_as_parameter_``, the handle of
    the object (a NULL handle destroys nothing). No Python function runs
    between the collection and the destruction, so a pending signal (Python
    raises it when a function starts) cannot skip the destruction.
    """

    __slots__ = ("_as_parameter_",)


# The references must outlive the objects for their callbacks to run, also
# when an object is part of a reference cycle. Each entry is removed by a
# second reference, whose callback is dict.pop: no Python function either.
_watched = {}
_exiting = False


def watch(obj, handle, destroy):
    """Call destroy(handle) when obj is collected, and return the reference
    that does it.

    ``handle`` is read at that time: a constructor that writes it makes obj the
    owner as soon as the C++ object exists. To cancel, set the reference's
    ``_as_parameter_`` to a NULL handle of the same type. Once the exit
    handlers that were registered after this module was imported have run,
    nothing is destroyed on collection any more (see _leave_alone).
    """
    armed = _Armed(obj, destroy)
    armed._as_parameter_ = handle
    key = id(armed)
    _watched[key] = armed, weakref.ref(obj, functools.partial(_watched.pop, key))
    # After registering: _leave_alone either sees the entry or set the flag first.
    if _exiting:
        armed._as_parameter_ = type(handle)()
    return armed


def _leave_alone():
    """Stop destroying the objects that are collected from now on: other
    threads may still be using them, and close() still destroys them."""
    global _exiting
    _exiting = True
    for armed, _ in list(_watched.values()):
        # Only ever a NULL handle: a concurrent close() also writes one.
        armed._as_parameter_ = type(armed._as_parameter_)()


