def to_items(value, length, name, allow_bytes=False):
    """The elements of a sequence of exactly ``length`` elements, as a list.

    Sets, mappings, iterators and strings are refused: they have no order, or
    are consumed, or are no sequence of values. A bytes-like object is only a
    sequence of bytes (allow_bytes).
    """
    if isinstance(value, (bytes, bytearray, memoryview)):
        if not allow_bytes:
            raise TypeError(f"argument {name!r} must be a sequence of numbers, not bytes")
        with memoryview(value) as view:
            if view.itemsize != 1:
                raise TypeError(f"argument {name!r} must be a bytes-like object of bytes")
            items = list(view.tobytes())
    elif (
        isinstance(value, (str, collections.abc.Mapping))
        or not hasattr(type(value), "__len__")
        or not hasattr(type(value), "__getitem__")
    ):
        raise TypeError(
            f"argument {name!r} must be a sequence of {length} elements, "
            f"not {_type_name(value)}"
        )
    else:
        items = list(value)
    if len(items) != length:
        raise ValueError(f"argument {name!r} must have {length} elements, got {len(items)}")
    return items


